T="teaching"
def tp(mod, prompt, a, b, ans, expl, pr, src, ctx=None, ma=None, mb=None):
    o=[{"text":a},{"text":b}]
    if ma: o[0]["mock"]=ma
    if mb: o[1]["mock"]=mb
    d=dict(type="pick",module=mod,prompt=prompt,options=o,answer=ans,evidence_type=T,metric="",source=src,explanation=expl,principles=pr)
    if ctx: d["context"]=ctx
    return d
def gb(mod, artifact, ans, expl, pr, src, mock=None, prompt="Good or bad? Rate it, then reveal the breakdown."):
    d=dict(type="goodbad",module=mod,prompt=prompt,artifact=artifact,answer=ans,evidence_type=T,metric="",source=src,explanation=expl,principles=pr)
    if mock: d["mock"]=mock
    return d
def ms(mod, artifact, flags, expl, pr, src, mock=None, notes=None):
    d=dict(type="missing",module=mod,prompt="What's missing or wrong? Tick everything that applies, then reveal.",artifact=artifact,answer=flags,evidence_type=T,metric="",source=src,explanation=expl,principles=pr)
    if mock: d["mock"]=mock
    if notes: d["flag_notes"]=notes
    return d
def wr(mod, brief, models, steps, checklist, pr, src, ev=T, extra=None):
    d=dict(type="write",module=mod,prompt=brief,model_answers=models,steps=steps,checklist=checklist,evidence_type=ev,metric="",source=src,explanation="Compare your draft with the models, then score yourself with the checklist.",principles=pr)
    if extra: d.update(extra)
    return d
def td(mod, title, parts, src, ev, pr, metric="", intro=""):
    return dict(type="teardown",module=mod,prompt=title,intro=intro,parts=parts,evidence_type=ev,metric=metric,source=src,explanation="Read each part and its annotation. Ask: could I reuse this move in my own ad?",principles=pr)

def M(**k):  # mock ad spec
    base=dict(page="Klinik Exempel",cta="Book now",bg="#e9eef6",fg="#14213d",overlay="",size="m",face=None,focal="one",contrast="high",headline="",badge="",clutter=0)
    base.update(k); return base

